function b(o){let n=0;for(const t of o||[])n+=Math.round(Number(t.purchase_price||0)*(Number(t.condition||0)/100));return n}function f(o,n){let t=0;const r=Number(n||0);for(const e of o||[]){if(e.status==="for_sale")continue;const a=Math.max(0,Math.floor((r-Number(e.built_at_tick||0))/12)),u=Math.max(.2,1-.05*a),i=Number(e.condition||0)/100;t+=Math.round(Number(e.purchase_price||0)*u*i)}return t}function d(o){const n={loans:0,bonds:0,insurance:0,total:0};for(const t of o||[]){const r=(t?.finance_loan_requests?.request_type||t?.request_type||"loan").toLowerCase(),e=Math.max(0,Number(t?.principal||0)),a=Math.max(0,Number(t?.remaining_principal||0));if(r==="insurance"){n.insurance+=e;continue}if(r==="bond"){n.bonds+=a>0?a:e;continue}n.loans+=a}return n.total=n.loans+n.bonds,n}function N({cash:o,loans:n,properties:t,propertyValue:r,vessels:e,equipmentValue:a,financeReceivables:u,currentTick:i}){const c=r!=null?Number(r):b(t),s=a!=null?Number(a):f(e,i),l=Math.max(0,Number(u||0)),p=Number(n||0),m=Number(o||0)+c+s+l-p;return{cash:Number(o||0),propertyValue:c,equipmentValue:s,financeReceivables:l,liabilities:p,valuationBasis:m,valuation:Math.round(m*1.3)}}function h({cash:o,loans:n,properties:t,propertyValue:r,vessels:e,equipmentValue:a,financeReceivables:u,currentTick:i}){return N({cash:o,loans:n,properties:t,propertyValue:r,vessels:e,equipmentValue:a,financeReceivables:u,currentTick:i}).valuation}export{d as a,N as b,f as c,b as d,h as e};
